USE fahizhub;
CREATE TABLE IF NOT EXISTS courses (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(190) NOT NULL,code VARCHAR(50),credit DECIMAL(4,2),semester VARCHAR(100),instructor VARCHAR(190),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assignments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,course_id BIGINT UNSIGNED,title VARCHAR(255) NOT NULL,deadline DATETIME,status ENUM('todo','in_progress','submitted','completed') DEFAULT 'todo',priority ENUM('low','medium','high','urgent') DEFAULT 'medium',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL,INDEX idx_assignments_deadline(status,deadline));
CREATE TABLE IF NOT EXISTS learning_goals (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,title VARCHAR(190) NOT NULL,description TEXT,status ENUM('planned','active','paused','completed') DEFAULT 'planned',progress TINYINT UNSIGNED DEFAULT 0,target_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_resources (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,goal_id BIGINT UNSIGNED,title VARCHAR(255) NOT NULL,url VARCHAR(500),notes TEXT,is_completed BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(goal_id) REFERENCES learning_goals(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS achievements (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,type ENUM('achievement','certification','award','workshop','competition','leadership','event') NOT NULL,title VARCHAR(255) NOT NULL,issuer VARCHAR(190),description TEXT,event_date DATE,credential_url VARCHAR(500),is_published BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,title VARCHAR(190) NOT NULL,description TEXT,technologies JSON,process TEXT,availability VARCHAR(190),is_published BOOLEAN DEFAULT FALSE,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analytics_events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,event_type VARCHAR(80) NOT NULL,path VARCHAR(500),entity_id BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_analytics_type_date(event_type,created_at));
